('7d000000-0000-4000-8000-000000000001','a01-espelho-partido','Espelho Partido','{"pt-BR":"Espelho Partido","en":"Shattered Mirror","es":"Espejo Roto"}','Recompor o Smart Mirror rachado em sete cacos com peças cuja cor dominante combina com a paleta de cada caco.','{"pt-BR":"Recompor o Smart Mirror rachado em sete cacos com peças cuja cor dominante combina com a paleta de cada caco.","en":"Piece the Smart Mirror, cracked into seven shards, back together with pieces whose dominant colour matches the palette of each shard.","es":"Recomponer el Smart Mirror, rajado en siete esquirlas, con prendas cuyo color dominante combine con la paleta de cada esquirla."}','livre','MEDIUM','ACTIVE',NULL,'[{"key":"caco_central","position":"VES","accepts":{},"label":{"pt-BR":"Caco central","en":"Centre shard","es":"Esquirla central"},"story":{"pt-BR":"Caco central: {name}{brand, select, none {} other { da {brand}}} devolve o primeiro reflexo inteiro ao quarto.","en":"Centre shard: {name}{brand, select, none {} other { by {brand}}} gives the room its first whole reflection back.","es":"Esquirla central: {name}{brand, select, none {} other { de {brand}}} devuelve al cuarto el primer reflejo entero."},"effects":{"comum":{"pt-BR":"O caco cola e reflete a peça; +1 sintonia se a cor bate com o caco vizinho.","en":"The shard sticks and reflects the piece; +1 sintonia if the colour matches the neighbouring shard.","es":"La esquirla se pega y refleja la prenda; +1 sintonía si el color coincide con la esquirla vecina."},"metamorfose":{"pt-BR":"O caco vira vidro-prisma e a paleta da peça tinge a parede atrás, dando +2 na vaga.","en":"The shard turns into prism glass and the palette of the piece tints the wall behind it, giving +2 on the slot.","es":"La esquirla se vuelve vidrio prisma y la paleta de la prenda tiñe la pared de atrás, dando +2 en la casilla."},"impersonation":{"pt-BR":"O avatar aparece no reflexo vestindo a peça e aprova a vaga, liberando uma troca gratuita.","en":"Your avatar app