('7d000000-0000-4000-8000-000000000031','b31-prova-com-a-estrela','Prova com a Estrela','{"pt-BR":"Prova com a Estrela","en":"Fitting with the Star","es":"Prueba con la Estrella"}','Vestir a estrela fictícia Lina Vale para três eventos, lendo o DNA de Estilo dela a cada prova.','{"pt-BR":"Vestir a estrela fictícia Lina Vale para três eventos, lendo o DNA de Estilo dela a cada prova.","en":"Dress the fictional star Lina Vale for three events, reading her Style DNA at every fitting.","es":"Vestir a la estrella ficticia Lina Vale para tres eventos, leyendo su ADN de Estilo en cada prueba."}','livre','HARD','ACTIVE',NULL,'[{"key":"coletiva_sup","position":"SUP","accepts":{},"label":{"pt-BR":"Coletiva: parte de cima","en":"Press conference: top","es":"Rueda de prensa: parte de arriba"},"story":{"pt-BR":"Para a coletiva, {name}{brand, select, none {} other { da {brand}}} veste Lina com sobriedade.","en":"For the press conference, {name}{brand, select, none {} other { by {brand}}} dresses Lina with restraint.","es":"Para la rueda de prensa, {name}{brand, select, none {} other { de {brand}}} viste a Lina con sobriedad."},"effects":{"comum":{"pt-BR":"Na coletiva: parte de cima, a confiança de Lina sobe ou cai conforme a sintonia com o DNA dela.","en":"At the press conference: top, Lina gains or loses confidence according to the harmony with her DNA.","es":"En la rueda de prensa: parte de arriba, la confianza de Lina sube o baja según la sintonía con su ADN."},"metamorfose":{"pt-BR":"Na coletiva: parte de cima, o manequim vira vidro e mostra a compatibilidade antes de confirmar.","en":"At the press conference: top, the mannequin turns to glass and shows the match before you confirm.","es":"En la rueda de prensa: parte de arriba, el maniquí se vuelve vidrio y muestra la compatibilidad antes de confirmar."},"impersonation":{"pt-BR":"Na coletiva: parte de cima, o avatar veste a peça ao lado de Lina e a confiança começa em 70.","en":"At the press conference: top, the avatar wears